              '6(a)(i)': { type: 'exact', points: ['C — movement of sodium ions into the neurone'], guidance: '1 mark.' },
              '6(a)(ii)': { type: 'points', points: ['(Voltage-gated) potassium channels open (allow potassium channels become (more) permeable)', 'and sodium channels close (allow sodium channels become impermeable)', 'so that potassium ions diffuse out of the neurone, repolarising the membrane (allow K⁺)'], guidance: '2 marks. Any two of the three points; each is a separate mark.' },
              '6(b)(i)': { type: 'exact', points: ['B — 1, 2 and 3'], guidance: '1 mark.' },
