              '21(c)(i)': { type: 'points', points: ['Because they have many mitochondria', 'Catalase activity may be (too) low (allow catalase may be inactive; allow low concentration of catalase)', 'Mutation in / less transcription of catalase gene', '(Or) SOD activity may be (too) high (allow high concentration of SOD)'], guidance: '2 marks, max 2 from 4 points.' },
