              '7': { type: 'exact', points: ['A'], guidance: '1 mark.' },
              '8': { type: 'exact', points: ['B'], guidance: '1 mark.' },
              '9': { type: 'exact', points: ['C'], guidance: '1 mark.' },
              '10': { type: 'exact', points: ['C'], guidance: '1 mark.' },
              '11': { type: 'exact', points: ['B'], guidance: '1 mark.' },
