              '01.3': { type: 'points', points: ['3.6(25) × 10⁻⁵ (mol dm⁻³ s⁻¹)'], guidance: '1 mark (AO1). Allow 3.59 x 10⁻⁵ to 3.63 x 10⁻⁵' },
