              '1(f)(i)': { type: 'points', points: ['pipettes 25 cm³ of Fe³⁺', 'adds excess iodide(to fully react with Fe³⁺);', 'titrate with thiosulfate solution in burette', 'starch indicator added near end point', 'repeat'], guidance: '5 marks (AO3.3; AO3.3; AO3.3; AO2.7; AO3.3).' },
              '1(f)(ii)': { type: 'points', points: ['(Amount thio =) 3.2 x 0.51/ 1000 or 1.63..... x 10⁻³ mol', '(Conc Fe³⁺ =) 1.63..... x 10⁻³ x 1000/25 = 0.065... mol dm⁻³', '2sf (0.065)'], guidance: '3 marks (AO2.8; AO2.8; AO3.1). Answer line: If answer = 0.065 (mol dm⁻³) award 3 marks. ALLOW ECF ALLOW Any calculated value to 2sf for 1 mark' },
              '1(f)(iii)': { type: 'points', points: ['Titre(AW) larger', 'Less measurement uncertainty/can quote answer to 3sf/smaller % error in titre. (AW)'], guidance: '2 marks (AO3.4 ×2). IGNORE references to accuracy/precision' },
              '1(g)': { type: 'points', points: ['⁴⁸₂₄Cr + ⁴₂He → ⁵²₂₆Fe: top row (48, 4, 52)', 'bottom row (24, 2, 26) and chromium symbol'], guidance: '2 marks (AO2.6 ×2).' },
