              '2(f)': { type: 'points', points: ['reactants with curly arrows: CH₃CH=CHCH₃ + HBr, curly arrow from C=C to H and from H–Br bond to Br [drawn]', 'intermediate attacked by bromide with curly arrow: CH₃CH₂C⁺HCH₃ + Br⁻ [drawn]', 'product: CH₃CH₂CHBrCH₃ [drawn]'], guidance: '3 marks (AO2.5 ×3). ALLOW any unambiguous structure curly arrows must start (when extended, if necessary) on the bond concerned or a lone pair or the negative charge on the bromide ion and end pointing at an atom or the bond to be formed. IGNORE partial charges.' },
              '2(g)': { type: 'points', points: ['Either Catalyst: Nickel AND Conditions: heat and pressure (between 1 and 5 atm)', 'or Catalyst: Platinum AND Conditions: RTP (AW)'], guidance: '1 mark (AO1.1). ALLOW T between 100oC and 200oC' },
              '2(h)(i)': { type: 'points', points: ['C₁₂H₂₆'], guidance: '1 mark (AO1.2).' },
