              '4(d)': { type: 'points', points: ['1. Upper fragment with NH₂ (shown circled) [structure drawn]', '2. Left hand fragment attached to serine contains =O', '3. his and asp structures completed as shown'], guidance: '3 marks (AO2.5 ×3).' },
              '4(e)(i)': { type: 'points', points: ['hydrogen bonds/imb broken in tertiary structure', 'so active site destroyed/changes shape/becomes denatured'], guidance: '2 marks (AO1.2 ×2). ALLOW H-bonds/imb disrupted(AW)' },
              '4(e)(ii)': { type: 'points', points: ['Shape with labelled axes (bell-shaped curve; y-axis activity/rate, x-axis pH) [drawn]', 'Peak of curve above pH 8', 'At other pH values the active site becomes denatured/changes shape'], guidance: '3 marks (AO2.7 ×3). y-axis labelled as ‘activity/rate/speed’ x-axis labelled pH' },
              '4(e)(iii)': { type: 'points', points: ['Correct for low/initial [substrate] / first order wrt low/initial [substrate]', 'At higher [substrate] becomes zero order/ rate does not depend on [substrate]'], guidance: '2 marks (AO3.1 ×2). ALLOW rate plateaus/levels off at higher [substrate]' },
              '5(a)(i)': { type: 'points', points: ['Ka = [H⁺][F⁻]/[HF]', 'mol dm⁻³'], guidance: '2 marks (AO1.1 ×2). ALLOW ecf' },
              '5(a)(ii)': { type: 'points', points: ['Ka = 7.24 x 10⁻⁴', 'Rearrangement of Ka expression to [F⁻]/[HF] = Ka/[H⁺] / 7.24x10⁻⁴/1x10⁻⁵', 'Ratio = 7.24 x 10⁻⁴/10⁻⁵ = 72.4'], guidance: '3 marks (AO2.6 ×3). Answer line: If answer = 72.4, award 3 marks. ALLOW 2 or more sf ALLOW ecf from (i) ALLOW ecf from second MP' },
              '5(b)': { type: 'points', points: ['PO₄³⁻', 'loss of proton/H⁺ from HPO₄²⁻'], guidance: '2 marks (AO2.1; AO1.1). ALLOW PO₄³⁻ accepts H⁺ MP2 dependent on MP1' },
              '5(c)': { type: 'points', points: ['SnF₂ + 2OH⁻ → Sn(OH)₂ + 2F⁻'], guidance: '1 mark (AO2.7). IGNORE state symbols' },
              '5(d)': { type: 'points', points: ['tetrahedral'], guidance: '1 mark (AO2.1).' },
